            RRUtils.RRIterator memory iter = RRUtils.iterateRRs(data, 0);
            !RRUtils.done(iter);
            RRUtils.next(iter)
        ) {
            if (_isTXTForName(iter, name)) {
                (resolver, context) = parseDNSSECRecord(
                    _readTXT(iter.data, iter.rdataOffset, iter.nextOffset)
                );
