        string calldata label,
        address owner,
        IRegistry registry,
        address resolver,
        uint256 roleBitmap,
        uint64 expiry
    )
        external
        returns (uint256 tokenId);

    /// @notice Renew a label.
    /// @param anyId The labelhash, token ID, or resource.
    /// @param newExpiry The new expiry, in seconds.
